// Deliberately narrow host bridge. Java programs get simulated carrier data only.
var DumbPipe={handleEvent:function(event){var e;try{e=JSON.parse(event.detail.message);}catch(_){return;}if(e.command!=='open')return;var data;if(e.type==='mobileInfo')data={network:{mcc:'460',mnc:'00'},icc:{mcc:'460',mnc:'00',msisdn:'00000000000'}};else if(e.type==='alert'){message.textContent=String(e.message).slice(0,200);return;}else if(e.type==='exit'){message.textContent='Java 程序已退出';return;}else {console.warn('Disabled Java host capability:',e.type);data={type:'error',error:'Unavailable in offline museum'};}setTimeout(function(){frame.contentWindow.postMessage({pipeID:e.pipeID,message:data},location.origin);},0);}};
function launchDemo(){releaseJavaKeys();gameReady=false;localJarData=null;localJarClass=null;var id=document.getElementById('demo').value;var cls={"snake": "OldSnake", "calculator": "PocketCalculator", "notes": "PocketNotes", "grid-tactics": "gridtactics.GridTacticsMIDlet", "pocket-saga": "pocketsaga.PocketSagaMIDlet", "monster-duel": "monsterduel.MonsterDuelMIDlet", "pixel-paddle": "pixelpaddle.PixelPaddleMIDlet", "brick-buster": "brickbuster.BrickBusterMIDlet", "pixel-jumper": "pixeljumper.PixelJumperMIDlet", "traffic-dash": "trafficdash.TrafficDashMIDlet", "block-fall": "blockfall.BlockFallMIDlet", "mine-sweep": "minesweep.MineSweepMIDlet", "keypad-chess": "keypadchess.KeypadChessMIDlet", "number-place": "numberplace.NumberPlaceMIDlet", "tower-guard": "towerguard.TowerGuardMIDlet", "star-defender": "stardefender.StarDefenderMIDlet", "dungeon-quest": "dungeonquest.DungeonQuestMIDlet", "pocket-farm": "pocketfarm.PocketFarmMIDlet"}[id];if(!cls)return;message.textContent='正在启动 '+cls+' · 首次加载约数秒';var folder=['snake','calculator','notes'].indexOf(id)>=0?'demos/':'open-games/';frame.src='main.html?jars='+folder+id+'.jar%3Fv=0.7.8&jad='+folder+id+'.jad%3Fv=0.7.8&midletClassName='+cls+'&autosize=1&fontSize=12';}
