document.getElementById('stop').onclick=function(){releaseJavaKeys();frame.src='about:blank';message.textContent='已停止，点击启动重新运行。';};
function key(code,down){if(code===-6){if(down)frame.contentDocument.getElementById("header-drawer-button")?.click();return;}if(code===-7){if(down)frame.contentDocument.querySelector("#header-ok-button button")?.click();return;}code=({"-1":119,"-2":115,"-3":97,"-4":100,"-5":32,"-6":112,"-7":8})[code]||code;try{var m=frame.contentWindow.MIDP;if(m)(down?m.sendKeyPress:m.sendKeyRelease)(code);}catch(_){}}
document.querySelectorAll('[data-key]').forEach(function(b){b.addEventListener('pointerdown',function(e){e.preventDefault();b.setPointerCapture(e.pointerId);setJavaKey(Number(b.dataset.key),true);});b.addEventListener('pointerup',function(){setJavaKey(Number(b.dataset.key),false);});b.addEventListener('pointercancel',function(){setJavaKey(Number(b.dataset.key),false);});});
var map={ArrowUp:-1,ArrowDown:-2,ArrowLeft:-3,ArrowRight:-4,Enter:-5,F1:-6,F2:-7};
['keydown','keyup'].forEach(function(type){window.addEventListener(type,function(e){if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;var c=map[e.key];if(c===undefined&&/^[0-9*#]$/.test(e.key))c=e.key.charCodeAt(0);if(c!==undefined){e.preventDefault();setJavaKey(c,type==='keydown');}});});
async function importLocalJar(file){if(file.size>8*1024*1024){message.textContent='请导入 8 MB 以内的 JAR。';publishGameStatus(message.textContent,false);return;}try{var data=await file.arrayBuffer(),zip=new ZipFile(data);var entry=zip.directory&&Object.keys(zip.directory).find(function(n){return n.toUpperCase()==='META-INF/MANIFEST.MF';});if(Object.keys(zip.directory||{}).length>5000||Object.values(zip.directory||{}).reduce(function(n,x){return n+(x.uncompressed_len||0);},0)>64*1024*1024)throw Error("large archive");if(entry&&zip.directory[entry].uncompressed_len>65536)throw Error("large manifest");var bytes=entry&&zip.read(entry);if(!bytes||bytes.length>65536)throw Error('manifest');var text=new TextDecoder().decode(bytes).replace(/\r\n?/g,'\n').replace(/\n /g,'');var line=text.split('\n').find(function(x){return /^MIDlet-1:\s*/i.test(x);});var cls=line&&line.split(',').pop().trim();if(!cls||!/^[\w.$]+$/.test(cls))throw Error('class');releaseJavaKeys();gameReady=false;localJarData=data;localJarClass=cls;localJarName=file.name;frame.src='main.html?jars=local.jar&jad=&midletClassName='+encodeURIComponent(cls)+'&autosize=1&fontSize=12';message.textContent='本机运行：'+file.name+' · 不上传';publishGameStatus('正在导入 '+file.name+' · 仅本机运行',false);}catch(_){message.textContent='无法读取 MIDlet-1 清单，请选择有效的 Java ME JAR。';publishGameStatus(message.textContent,false);}}
document.getElementById('jar').onchange=function(e){if(e.target.files[0])importLocalJar(e.target.files[0]);};
